def min_absolute_value(X, K, D):
    # If K is even, the minimum absolute value is always 0
    if K % 2 == 0:
        return 0

    # If K is odd, we need to consider the parity of X and D
    if X % 2 == D % 2:
        return abs(X - K * D)
    else:
        return abs(X - K * D + D)

